{-# LANGUAGE OverloadedRecordDot #-}

-- | The CEL compilers behind the Impetus kernel seam.
--
-- * A port of the reference's @tests/petrus/impetus/binding/test_cel.py@
--   (all 19 tests), against 'celCompilers' and the kernel's own types.
-- * The five CEL tests @packages/petrus-impetus/PARITY.md@ leaves to this
--   package (@test_completion.py::TestCelEnvironment@ x3,
--   @TestCompletionValidation@ and @test_cel_guards.py::TestCelGuardValidation@
--   macro-bound variables), on real Instances.
-- * The end-to-end corpus @test/corpus/cel-instance.json@, generated by
--   @test/gen-cel-instance.py@ from the reference: Instances whose nets
--   declare inline CEL guards, arc filters, and completion conditions,
--   compared step by step (candidates, enabledness diagnostics, firing
--   outcomes, markings), then by status, completion diagnostics, and the
--   complete encoded History.
module Impetus
  ( spec
  , celInstanceCases
  , startCelCase
  , caseSteps
  ) where

import Control.Monad (forM_, zipWithM_)
import Data.ByteString qualified as BS
import Data.Map.Strict qualified as Map
import Data.Set qualified as Set
import Data.Text (Text)
import Data.Text qualified as T
import Test.Hspec hiding (pending)

import Data.Text.Encoding (decodeUtf8)
import Petrus.Cel (compile, freeVariables)
import Petrus.Cel.Binding (macros)
import Petrus.Cel.Impetus (celCompilers)
import Petrus.Impetus.Binding (CelCompilers (..))
import Petrus.Impetus.History.Codec (encodeRecord)
import Petrus.Impetus.HistoryStore qualified as Store
import Petrus.Impetus.Instance
import Petrus.Impetus.NetDefinition (compileNetDefinition, parseNetDefinitionText)
import Petrus.Impetus.Petrinet hiding (candidates, candidatesWithDiagnostics, nextMaturation, outputs, token)
import Petrus.Json
import Petrus.TestSupport (readUpstream)

np :: Text -> NetPath
np = either (error . T.unpack) id . netPath

tokD :: Text -> Json -> Token
tokD c = Token (Just c)

obj :: [(Text, Json)] -> Json
obj = Object

expectRight :: (HasCallStack, Show e) => Either e a -> IO a
expectRight = \case
  Right a -> pure a
  Left e -> expectationFailure ("expected Right, got Left " <> show e) >> error "unreachable"

shouldBeLeftContaining :: (HasCallStack) => Either Text a -> Text -> Expectation
shouldBeLeftContaining result needle = case result of
  Left message -> message `shouldSatisfy` T.isInfixOf needle
  Right _ -> expectationFailure ("expected Left containing " <> show needle)

filterOf :: Text -> Either Text Filter
filterOf = celCompilers.compileFilter . unsafeCel

completionOf :: Text -> [NetPath] -> Either Text (Marking -> Either Text Bool)
completionOf expression = celCompilers.compileCompletion (unsafeCel expression)

guardOf :: Text -> NetPath -> [NetPath] -> Either Text Guard
guardOf expression at scope = celCompilers.compileGuard (unsafeCel expression) at (Set.fromList scope)

spec :: Spec
spec = describe "Petrus.Cel.Impetus" $ do
  bindingSpec
  paritySpec
  endToEndSpec

-- ---------------------------------------------------------------------------
-- tests/petrus/impetus/binding/test_cel.py

bindingSpec :: Spec
bindingSpec = describe "binding/test_cel.py" $ do
  describe "compile_filter" $ do
    it "a compiled filter evaluates bare data fields" $ do
      f <- expectRight (filterOf "amount >= 100")
      f (tokD "Payment" (obj [("amount", Int 150)])) `shouldBe` Right True
      f (tokD "Payment" (obj [("amount", Int 40)])) `shouldBe` Right False
    it "an invalid expression fails at compile and never evaluates" $
      (filterOf "amount >=" >> Right ()) `shouldBeLeftContaining` "invalid CEL"
    it "non-mapping data raises for enabledness to read as not admitted" $ do
      f <- expectRight (filterOf "amount >= 100")
      f black `shouldBe` Left "TypeError('CEL filters read data fields; token data is NoneType, not a mapping')"

  describe "compile_completion" $ do
    let places = [np "done", np "pending"]
    it "a compiled completion evaluates places as token struct lists" $ do
      c <- expectRight (completionOf "done.exists(t, t.data.state == \"ok\") && size(pending) == 0" places)
      c (markingFromList [(np "done", [tokD "Result" (obj [("state", String "ok")])])]) `shouldBe` Right True
      c (markingFromList [(np "done", [tokD "Result" (obj [("state", String "failed")])])]) `shouldBe` Right False
    it "every declared place is bound even when the marking is sparse" $ do
      c <- expectRight (completionOf "size(done) == 0 && size(pending) == 0" places)
      c (markingFromList []) `shouldBe` Right True
    it "an invalid expression fails at compile and never evaluates" $
      (completionOf "size(done) ==" places >> Right ()) `shouldBeLeftContaining` "invalid CEL"
    it "an unknown place reference fails at compile" $
      (completionOf "size(doen) > 0" places >> Right ()) `shouldBeLeftContaining` "doen"
    it "macro-bound variables are not free place references" $
      (completionOf "done.exists(t, t.color == null) && size(done) >= 1" places >> Right ()) `shouldBe` Right ()

  describe "compile_guard" $ do
    let scope = [np "pending", np "config"]
        approve = np "approve"
        binding amount limit =
          Binding
            approve
            [(np "pending", [tokD "Payment" (obj [("amount", Int amount)])])]
            [(np "config", [tokD "Config" (obj [("limit", Int limit)])])]
            []
    it "place variables bind the binding's selected tokens" $ do
      g <- expectRight (guardOf "pending[0].data.amount <= config[0].data.limit" approve scope)
      g (binding 150 200) `shouldBe` Right True
      g (binding 150 100) `shouldBe` Right False
    it "a black token reads as null color and data" $ do
      g <- expectRight (guardOf "pending[0].color == null && pending[0].data == null" approve scope)
      g (Binding approve [(np "pending", [black])] [] []) `shouldBe` Right True
    it "a weighted selection binds as a list" $ do
      g <- expectRight (guardOf "pending.all(t, t.data.amount < 500)" approve scope)
      let tokens = [tokD "Payment" (obj [("amount", Int 150)]), tokD "Payment" (obj [("amount", Int 40)])]
      g (Binding approve [(np "pending", tokens)] [] []) `shouldBe` Right True
    it "consumed selections precede read selections from the same place" $ do
      g <- expectRight (guardOf "pending[0].data.kind == \"consumed\" && pending[1].data.kind == \"read\"" approve scope)
      g
        ( Binding
            approve
            [(np "pending", [tokD "X" (obj [("kind", String "consumed")])])]
            [(np "pending", [tokD "X" (obj [("kind", String "read")])])]
            []
        )
        `shouldBe` Right True
    it "an invalid expression fails at compile and never evaluates" $
      (guardOf "pending[0].data.amount >=" approve scope >> Right ()) `shouldBeLeftContaining` "invalid CEL"
    it "a reference outside the supplied places fails at compile" $
      (guardOf "elsewhere[0].data.amount >= 100" approve scope >> Right ())
        `shouldBe` Left
          "CEL guard 'elsewhere[0].data.amount >= 100' on transition approve references name(s) outside its consume/read input places ['config', 'pending']: ['elsewhere']"
    it "macro-bound variables are not place references" $
      (guardOf "pending.all(t, t.data.amount < 500)" approve scope >> Right ()) `shouldBe` Right ()
    it "evaluation errors on a concrete binding propagate" $ do
      g <- expectRight (guardOf "pending[0].data.amount >= 100" approve scope)
      g (Binding approve [(np "pending", [black])] [] [])
        `shouldBe` Left
          "CELEvalError(*(\"None with type: '<class 'NoneType'>' does not support field selection\", <class 'TypeError'>, None), tree='pending[0].data.amount')"

  describe "free_variables" $ do
    let free expression = either (error . show) (Set.toList . freeVariables) (compile expression)
    it "variable-position idents are free, call-position names are not" $
      free "size(done) > 0 && pending[0].color == null" `shouldBe` ["done", "pending"]
    it "macro-bound variables are subtracted across nesting" $
      free "a.exists(t, b.exists(u, u.x == t.y)) && size(c) > 0" `shouldBe` ["a", "b", "c"]
    it "a macro variable shadowing a place name is permissively skipped" $
      free "pending.exists(done, done.color == null) && size(done) == 0" `shouldBe` ["pending"]
    -- Beyond upstream: MACROS as named API (Petrus.Cel.Binding.macros), read
    -- back from the pinned reference's source.
    it "MACROS is the pinned reference's set" $ do
      source <- decodeUtf8 <$> readUpstream "src/petrus/impetus/binding/cel.py"
      let declared = [l | l <- T.lines source, "MACROS = frozenset({" `T.isPrefixOf` l]
          quoted l = [name | (i, name) <- zip [0 :: Int ..] (T.splitOn "\"" l), odd i]
      map (Set.fromList . quoted) declared `shouldBe` [macros]
      Set.size macros `shouldBe` 5

-- ---------------------------------------------------------------------------
-- The five CEL tests PARITY.md leaves to petrus-cel

-- | a -> t -> b, with a CEL completion condition.
chain :: Text -> Net
chain expression =
  either (error . T.unpack) id $
    mkNet
      (netSpec [place pa, place pb] [transition tt] [arc pa tt, arc tt pb])
        { completion = Just (CompletionCel (unsafeCel expression))
        }
  where
    pa = np "a"
    tt = np "t"
    pb = np "b"

withCel :: Net -> Marking -> IO (Either InstanceError Instance)
withCel net m = newInstance net defaultInstanceConfig {initialMarking = m, celCompilers = celCompilers}

ranStatus :: Net -> Marking -> IO Status
ranStatus net m = do
  inst <- withCel net m >>= expectRight
  _ <- run inst >>= expectRight
  status inst

paritySpec :: Spec
paritySpec = describe "PARITY.md CEL tests on Instances" $ do
  let pa = np "a"
  -- test_completion.py::TestCelEnvironment.test_place_variables_bind_token_color_and_data
  it "place variables bind token color and data" $
    ranStatus
      (chain "b.exists(t, t.color == \"Payment\" && t.data.amount >= 100)")
      (markingFromList [(pa, [tokD "Payment" (obj [("amount", Int 150)])])])
      `shouldReturn` Completed
  -- test_completion.py::TestCelEnvironment.test_a_black_token_reads_as_null_color_and_data
  it "a black token reads as null color and data" $
    ranStatus (chain "b.exists(t, t.color == \"Payment\")") (markingFromList [(pa, [black])]) `shouldReturn` Stuck
  -- test_completion.py::TestCelEnvironment.test_an_empty_place_binds_to_the_empty_list
  it "an empty place binds to the empty list" $
    ranStatus (chain "size(a) == 0 && size(b) == 1") (markingFromList [(pa, [black])]) `shouldReturn` Completed
  -- test_completion.py::TestCompletionValidation.test_macro_bound_variables_are_not_place_references
  it "completion: macro-bound variables are not place references" $ do
    result <- withCel (chain "b.exists(t, t.color == null)") (markingFromList [])
    either (Left . renderInstanceError) (const (Right ())) result `shouldBe` Right ()
  -- test_cel_guards.py::TestCelGuardValidation.test_macro_bound_variables_are_not_place_references
  it "guard: macro-bound variables are not place references" $ do
    let p = np "p"
        t = np "t"
        out = np "out"
        net =
          either (error . T.unpack) id $
            mkNet
              ( netSpec
                  [place p, place (np "q"), place out]
                  [Transition t Nothing [GuardCel (unsafeCel "p.all(t, t.data.n > 0)")] []]
                  [arc p t, arc t out]
              )
    result <- withCel net (markingFromList [])
    either (Left . renderInstanceError) (const (Right ())) result `shouldBe` Right ()

-- ---------------------------------------------------------------------------
-- End-to-end Instances against the reference

endToEndSpec :: Spec
endToEndSpec = describe "end-to-end Instances (test/corpus/cel-instance.json)" $ do
  cases <- runIO celInstanceCases
  it "carries the generated cases" $ length cases `shouldSatisfy` (>= 5)
  forM_ cases $ \c -> it (T.unpack (text (member "name" c))) (replayCase c)

-- | The committed corpus's cases.
celInstanceCases :: IO [Json]
celInstanceCases = do
  raw <- BS.readFile "test/corpus/cel-instance.json"
  pure $ case parseJson pythonLoads raw of
    Right corpus | Just (Array xs) <- lookupMember "cases" corpus -> xs
    _ -> error "cel-instance corpus: no cases"

-- | A case's net (compiled from its canonical definition) and a fresh
-- Instance over it on the real CEL compilers, as the generator built it.
startCelCase :: Json -> IO (Net, Instance)
startCelCase c = do
  definition <- either (fail . T.unpack) pure (parseNetDefinitionText (text (member "definition" c)))
  net <- either (fail . T.unpack) pure (compileNetDefinition definition)
  let initial = markingFromList [(np (text (member "place" e)), map decodeToken (array (member "tokens" e))) | e <- array (member "initialMarking" c)]
  inst <-
    newInstance
      net
      defaultInstanceConfig
        { initialMarking = initial
        , celCompilers = celCompilers
        , suppliedIdentity = Just ("cel-" <> text (member "name" c))
        }
      >>= either (fail . T.unpack . renderInstanceError) pure
  pure (net, inst)

-- | The recorded steps (one @step@ each).
caseSteps :: Json -> [Json]
caseSteps c = array (member "steps" c)

replayCase :: Json -> Expectation
replayCase c = do
  (_, inst) <- startCelCase c
  let name = T.unpack (text (member "name" c))
  forM_ (zip [0 :: Int ..] (caseSteps c)) $ \(index, stepJson) -> do
    let label field = name <> " step " <> show index <> " " <> field
    (enabled, diagnostics) <- candidatesWithDiagnostics inst
    same (label "candidatesBefore") (Array (map encodeBinding enabled)) (member "candidatesBefore" stepJson)
    same (label "diagnosticsBefore") (Array (map (String . renderDiagnostic) diagnostics)) (member "diagnosticsBefore" stepJson)
    outcome <- step inst Nothing >>= either (fail . T.unpack . renderInstanceError) pure
    same (label "outcome") (maybe Null encodeOutcome outcome) (member "outcome" stepJson)
    current <- marking inst
    same (label "markingAfter") (encodeMarking current) (member "markingAfter" stepJson)
  (finalStatus, statusDiagnostics) <- statusWithDiagnostics inst
  same (name <> " status") (String (statusText finalStatus)) (member "status" c)
  let completionDiagnostics = [d | String d <- array (member "statusDiagnostics" c), "completion condition " `T.isPrefixOf` d]
  same (name <> " status diagnostics") (Array (map String statusDiagnostics)) (Array (map String completionDiagnostics))
  history <- Store.records (instanceHistory inst)
  let expected = array (member "history" c)
  length history `shouldBe` length expected
  zipWithM_ (\i (r, e) -> same (name <> " history record " <> show i) (encodeRecord r) e) [0 :: Int ..] (zip history expected)

encodeToken :: Token -> Json
encodeToken t = Object [("color", maybe Null String t.color), ("data", t.payload)]

decodeToken :: Json -> Token
decodeToken j = Token (case member "color" j of String s -> Just s; _ -> Nothing) (member "data" j)

encodeSelections :: [(NetPath, [Token])] -> Json
encodeSelections xs = Array [Object [("place", String (netPathText p)), ("tokens", Array (map encodeToken ts))] | (p, ts) <- xs]

encodeBinding :: Binding -> Json
encodeBinding b =
  Object
    [ ("transition", String (netPathText b.transition))
    , ("consumed", encodeSelections b.consumed)
    , ("read", encodeSelections b.read)
    , ("delivered", Array (map encodeToken b.delivered))
    ]

encodeMarking :: Marking -> Json
encodeMarking m = encodeSelections (Map.toAscList (Map.fromList [(netPathText p, ts) | (p, ts) <- markingToList m]) `asPlaces` ())
  where
    asPlaces xs () = [(np p, ts) | (p, ts) <- xs]

encodeOutcome :: FiringOutcome -> Json
encodeOutcome o =
  Object
    [ ("occurrence", Int (fromIntegral o.occurrence))
    , ("transition", String (netPathText o.transition))
    , ("consumed", Array (map encodeToken o.consumed))
    , ("produced", Array [Object [("place", String (netPathText p)), ("token", encodeToken t)] | (p, t) <- o.produced])
    ]

member :: Text -> Json -> Json
member key j = maybe (error ("cel-instance corpus: missing " <> T.unpack key)) id (lookupMember key j)

text :: Json -> Text
text = \case
  String s -> s
  other -> error ("cel-instance corpus: expected a string, got " <> show other)

array :: Json -> [Json]
array = \case
  Array xs -> xs
  other -> error ("cel-instance corpus: expected an array, got " <> show other)

-- | Compare by canonical spelling, so @1@ and @1.0@ differ as on the wire.
same :: (HasCallStack) => String -> Json -> Json -> Expectation
same label got want =
  let spell = canonicalText
   in if spell got == spell want
        then pure ()
        else expectationFailure (label <> ":\n  got      " <> show (spell got) <> "\n  expected " <> show (spell want))
